#!/usr/bin/env node
/*
 * check-digest-version.js — belt-and-braces CI guard for the roadmap digest.
 *
 * Usage:
 *   node check-digest-version.js [<roadmap.html> <digest.md>]
 *   (defaults: docs/reference-roadmap.html docs/roadmap-digest.md)
 *
 * The digest is regenerated by the roadmap-edit skill (gen-roadmap-digest.js)
 * from the roadmap HTML and committed alongside it. This CI guard does not
 * regenerate; it only VERIFIES that the two committed files agree on version.
 * That catches the one failure this setup allows: a half-update — HTML changed
 * but digest not regenerated, or vice versa.
 *
 * It compares the `vMAJOR.MINOR · updated <date>, <time>` identity extracted
 * from each file. Both files are tracked, so one that will not read or will not
 * parse is BROKEN, not a finding — see scripts/lib/check.js for the alphabet.
 */

const fs = require("node:fs");
const { runCheck } = require("./lib/check");
const { caught } = require("./lib/caught.js");

/** @typedef {import("./lib/check").CheckContext} Ctx */

// The shared identity: "v5.21 · updated 8 July 2026, 19:00".
// Bounded so a trailing " · 107 cards" (digest) or "</p>" (html) is excluded.
const VERSION_RE = /v\d+\.\d+ · updated [^·<\n]+/;

runCheck({
	name: "digest-version",
	module: "roadmap",
	usage: "node check-digest-version.js [<roadmap.html> <digest.md>]",
	run(/** @type {Ctx} */ ctx) {
		const htmlPath = ctx.args[0] || "docs/reference-roadmap.html";
		const digestPath = ctx.args[1] || "docs/roadmap-digest.md";

		const extract = (/** @type {string} */ p, /** @type {string} */ label) => {
			let text;
			try {
				text = fs.readFileSync(p, "utf8");
			} catch (e) {
				ctx.broken(`cannot read ${label} at ${p} — ${caught(e).message}`);
			}
			const m = text.match(VERSION_RE);
			if (!m) ctx.broken(`no version line found in ${label} (${p})`);
			return m[0].trim();
		};

		const htmlVer = extract(htmlPath, "roadmap HTML");
		const digestVer = extract(digestPath, "digest");

		if (htmlVer !== digestVer) {
			ctx.fail(
				"DRIFT",
				"roadmap HTML and digest version lines have drifted.",
				{
					html: htmlVer,
					digest: digestVer,
				},
				`DRIFT\t${digestPath}`,
			);
			// No severity prefix here: check.js owns the one `SEVERITY:` line a run
			// emits, and prints it after this detail.
			ctx.say("The roadmap HTML and digest version lines have drifted.");
			ctx.say(`  HTML   (${htmlPath}):   ${htmlVer}`);
			ctx.say(`  digest (${digestPath}): ${digestVer}`);
			ctx.say(
				"\nThe digest is derived from the HTML by the roadmap-edit skill and the " +
					"two must be committed together. Regenerate the digest from the current " +
					"HTML (gen-roadmap-digest.js) and commit both files.",
			);
			return { noun: "version line(s) drifted" };
		}

		return { okLine: `roadmap HTML and digest agree — ${htmlVer}` };
	},
});
